// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(1000, "", ""); }
    function testFuzz_property(uint256 _value) public {
        uint256 maxBurn = c.balanceOf(address(this));
        vm.assume(_value > 0 && _value <= maxBurn);
        uint256 balanceBefore = c.balanceOf(address(this));
        c.burn(_value);
        uint256 balanceAfter = c.balanceOf(address(this));
        assertTrue(balanceAfter == balanceBefore - _value);
    }
}

